-- Seeded from the user-provided walmart-products.csv, not the old database.
-- Historical prices: 1 USD = 1350 KRW, rounded to 100 KRW.
-- Twelve source IDs selected in the previously reviewed research materials.
begin;
on conflict(source_product_id) do update set dataset_version=excluded.dataset_version,profile_codes=excluded.profile_codes,name_original=excluded.name_original,name_ko=excluded.name_ko,description_original=excluded.description_original,image_url=excluded.image_url,category=excluded.category,price_original_usd=excluded.price_original_usd,price_krw=excluded.price_krw,fx_rule=excluded.fx_rule,source_url=excluded.source_url,reviewed=excluded.reviewed;
commit;
